d="import { useState, useEffect } from 'react'\nimport { useParams, useNavigate } from 'react-router-dom'\nimport { Card, Badge, Button, Avatar, Spinner } from '@/components/ui'\nimport { ArrowLeft, Mail, Phone, Calendar, AlertTriangle, ClipboardList, MessageSquare, FileText, Edit2 } from 'lucide-react'\nimport { alertsApi } from '@/services/alertsApi'\n\nexport function DentistPatientDetailPage() {\n  const { id } = useParams()\n  const navigate = useNavigate()\n  const [patient, setPatient] = useState<any>(null)\n  const [appointments, setAppointments] = useState<any[]>([])\n  const [intakes, setIntakes] = useState<any[]>([])\n  const [alerts, setAlerts] = useState<any[]>([])\n  const [loading, setLoading] = useState(true)\n  const [aiSummary, setAiSummary] = useState('')\n  const [generating, setGenerating] = useState(false)\n  const [activeTab, setActiveTab] = useState<'overview' | 'appointments' | 'intake' | 'notes'>('overview')\n\n  useEffect(() => { if (id) loadPatientData() }, [id])\n\n  const loadPatientData = async () => {\n    setLoading(true)\n    try {\n      setPatient({ id: id!, full_name: 'Sarah Johnson', email: 'sarah@email.com', phone: '+1 (555) 123-4567', created_at: '2026-01-15' })\n      setAppointments([{ id: '1', date: '2026-09-03', start: '10:00', end_time: '10:30', type: 'checkup', status: 'completed', dentist_name: 'Dr. Smith', notes: 'Routine checkup' }])\n      setIntakes([{ id: '1', chief_complaint: 'Tooth pain in lower right area', location: 'Lower right molar', duration: '3 days', pain_level: 7, swelling: true, sensitivity: true, created_at: '2026-09-01' }])\n      const alertRes = await alertsApi.getPatientAlerts(id!)\n      setAlerts(alertRes.alerts)\n    } catch (err) { console.error('Failed to load', err) }\n    finally { setLoading(false) }\n  }\n\n  const generateAiSummary = async () => {\n    setGenerating(true)\n    await new Promise(r => setTimeout(r, 1500))\n    const latestIntake = intakes[0]\n    if (latestIntake) { setAiSummary('Patient presents with ' + latestIntake.chief_complaint + '. Location: ' + latestIntake.location + '. Pain level: ' + latestIntake.pain_level + '/10. ' + (latestIntake.swelling ? 'Mild swelling. ' : '') + 'Evaluate for intervention.') }\n    setGenerating(false)\n  }\n\n  if (loading) return <div className=\"flex justify-center items-center min-h-[400px]\"><Spinner size=\"lg\" /></div>\n  if (!patient) return <div className=\"p-8 text-center\">Patient not found</div>\n\n  const latestIntake = intakes[0]\n  return (\n    <div className=\"space-y-6\">\n      <div className=\"flex items-center justify-between\">\n        <div className=\"flex items-center gap-4\">\n          <button onClick={() => navigate(-1)} className=\"p-2 hover:bg-neutral-100 rounded-lg\"><ArrowLeft className=\"w-5 h-5\" /></button>\n          <Avatar firstName={patient.full_name.split(' ')[0]} lastName={patient.full_name.split(' ')[1] || ''} size=\"lg\" />\n          <div><h1 className=\"text-2xl font-bold\">{patient.full_name}</h1><p className=\"text-neutral-500 text-sm\">Patient since {new Date(patient.created_at).toLocaleDateString()}</p></div>\n        </div>\n        <div className=\"flex items-center gap-2\"><Button variant=\"outline\" size=\"sm\"><Edit2 className=\"w-4 h-4 mr-2\" />Edit</Button><Button variant=\"outline\" size=\"sm\"><Calendar className=\"w-4 h-4 mr-2\" />Book</Button></div>\n      </div>\n      <div className=\"border-b\">\n        <nav className=\"flex gap-6\">\n          {(['overview', 'appointments', 'intake', 'notes'] as const).map(tab => (\n            <button key={tab} onClick={() => setActiveTab(tab)} className={'pb-3 px-1 text-sm font-medium border-b-2 capitalize ' + (activeTab === tab ? 'border-primary-600 text-primary-600' : 'border-transparent text-neutral-500 hover:text-neutral-700')}>{tab}</button>\n          ))}\n        </nav>\n      </div>\n      <div className=\"grid lg:grid-cols-3 gap-6\">\n        <div className=\"space-y-4\">\n          <Card><div className=\"p-4 border-b\"><h2 className=\"font-semibold\">Patient Information</h2></div><div className=\"p-4 space-y-4\"><div className=\"flex items-center gap-3\"><Mail className=\"w-4 h-4 text-neutral-400\" /><span className=\"text-sm\">{patient.email}</span></div><div className=\"flex items-center gap-3\"><Phone className=\"w-4 h-4 text-neutral-400\" /><span className=\"text-sm\">{patient.phone || 'No phone'}</span></div></div></Card>\n          {alerts.length > 0 && (\n            <Card className=\"border-red-200 bg-red-50/50\">\n              <div className=\"p-4 border-b border-red-200 flex items-center gap-2\"><AlertTriangle className=\"w-4 h-4 text-red-600\" /><h2 className=\"font-semibold text-red-800\">Active Alerts</h2></div>\n              <div className=\"p-4 space-y-3\">{alerts.map(alert => (<div key={alert.id} className=\"p-3 bg-white rounded-lg border border-red-100\"><div className=\"flex items-center justify-between mb-1\"><span className={'px-2 py-0.5 text-xs font-medium rounded ' + (alert.severity === 'CRITICAL' ? 'bg-red-100 text-red-800' : 'bg-amber-100 text-amber-800')}>{alert.severity}</span><span className=\"text-xs text-neutral-500\">{new Date(alert.created_at).toLocaleDateString()}</span></div><p className=\"text-sm\">{alert.reason_codes.join(', ')}</p></div>))}</div>\n            </Card>\n          )}\n        </div>\n        <div className=\"lg:col-span-2 space-y-4\">"
n=open('e:/DENTALAIAGENT/frontend/src/pages/dentist/DentistPatientDetailPage.tsx','w',encoding='utf-8')
